{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Aromatherapy Membership in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="A safety-first aromatherapy membership blending ritual, science-informed practice, and fragrant storytelling. Join {{PRACTITIONER_NAME}} for seasonal blends and guided sessions." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="earthy">
  <header class="site-header">
    <div class="container nav-wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="mainNav">
        <a href="/">Home</a>
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Boutique</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">About</a>
        <a href="/book.html">Book</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <button class="nav-toggle" id="navToggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1>Where scent becomes a gentle ceremony</h1>
          <p class="lead">Steady, safety-first aromatherapy with a membership that guides you through seasonal rituals, custom blends, and evidence-informed practice.</p>
          <div class="hero-actions">
            <a class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
          </div>
          <p class="small">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div class="hero-art">
          <svg class="bottle" viewBox="0 0 200 260" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="illustration of an oil bottle">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#C89A6B" />
                <stop offset="1" stop-color="#6B8E6B" />
              </linearGradient>
            </defs>
            <rect x="20" y="60" rx="18" ry="18" width="160" height="160" fill="url(#g1)" opacity="0.95" />
            <ellipse cx="100" cy="220" rx="60" ry="14" fill="#7A5B3B" opacity="0.25" />
            <rect x="78" y="20" width="44" height="40" rx="8" fill="#4B3A2B" />
            <g fill="#FFF" opacity="0.06">
              <path d="M40 90c12-18 28-28 60-28s48 10 60 28" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- Myth vs Truth -->
    <section class="myth-truth container">
      <h2>Myths unraveled, with care</h2>
      <p class="intro">Aromatherapy carries stories. Here we sort folklore from safe practice—gentle, clear, and client-centered.</p>
      <div class="cards">
        <div class="card">
          <h3>Myth: Essential oils cure illnesses</h3>
          <p class="truth">Truth: Oils are supportive tools for comfort, ritual, and wellbeing. They are not a replacement for medical care; we stay safety-first and evidence-informed.</p>
        </div>
        <div class="card">
          <h3>Myth: Natural always means safe</h3>
          <p class="truth">Truth: "Natural" is not a guarantee. Proper dilution, patch-testing, and attention to pregnancy, meds, and pets make use safer.</p>
        </div>
        <div class="card">
          <h3>Myth: More makes it stronger</h3>
          <p class="truth">Truth: With scent, less is more. We prioritize mindful dosing and guided application over heavy fragrance.</p>
        </div>
      </div>
    </section>

    <!-- Pillars -->
    <section class="pillars">
      <div class="container">
        <h2>Our practice pillars</h2>
        <div class="grid-3">
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#D9B99B"/></svg>
            <h3>Safety-First Rituals</h3>
            <p>Every blend and recommendation includes dilution guidance, contraindication checks, and patch test instructions.</p>
          </div>
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" fill="#A3B38A"/></svg>
            <h3>Personalized Craft</h3>
            <p>Membership members receive seasonal blends and a yearly review; we tailor suggestions to life stage and context.</p>
          </div>
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24"><path d="M2 20h20" stroke="#8B6040" stroke-width="2"/></svg>
            <h3>Stories & Skills</h3>
            <p>We teach safe techniques—diffusion, roll-on prep, and mindful inhalation—so clients gain skills, not just scents.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Case Notes (anonymized) -->
    <section class="case-notes container">
      <h2>Case notes: thoughtful snapshots</h2>
      <p class="intro">Anonymized notes to show process, not promises.</p>
      <div class="note-list">
        <article class="note">
          <h4>Evening wind-down ritual</h4>
          <p><strong>Context:</strong> client sought calmer evenings; not taking meds; no pregnancy.</p>
          <p><strong>Intervention:</strong> guided 2% lavender-cedar roll-on for wrists; 10-minute evening inhalation practice; patch test arranged.</p>
          <p><strong>Outcome:</strong> client reported improved sense of ritual and subjective relaxation after 3 sessions; no adverse effects.</p>
        </article>
        <article class="note">
          <h4>Seasonal support—work stress</h4>
          <p><strong>Context:</strong> high work stress, cat in home. Reviewed pet-safe diffusion durations.</p>
          <p><strong>Intervention:</strong> diffuse bergamot-blend 20 minutes, twice daily; no direct skin application near pets; dilution 1% when using roll-ons.</p>
          <p><strong>Outcome:</strong> client reported better focus; monitored pet behavior with no concerns.</p>
        </article>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq container" id="faq">
      <h2>Frequently asked (safety-focused)</h2>
      <div class="faq-grid">
        <div class="faq-item">
          <h4>What dilution should I use?</h4>
          <p>We recommend 0.5–2% for general use with adults depending on application. Children and sensitive skin require lower dilutions. As a membership benefit, we provide dilution charts for common applications.</p>
        </div>
        <div class="faq-item">
          <h4>How do I patch test?</h4>
          <p>Apply one drop of a 1% dilution on the inside forearm, cover, and observe for 24–48 hours. If redness, itching, or irritation appears, discontinue and consult your practitioner.</p>
        </div>
        <div class="faq-item">
          <h4>Are essential oils safe around pets?</h4>
          <p>Many oils can affect pets—especially cats and birds. We give pet-safe diffusion protocols, limit exposure time, and list oils to avoid. Always monitor your animal and consult a veterinarian for specific concerns.</p>
        </div>
        <div class="faq-item">
          <h4>What about pregnancy and breastfeeding?</h4>
          <p>Some oils are contraindicated in pregnancy or require specialist approval. We ask pregnant or breastfeeding clients to share status before any recommendation and rely on up-to-date safety references.</p>
        </div>
        <div class="faq-item">
          <h4>Can I use oils with medications?</h4>
          <p>Certain oils may interact or be inadvisable with some medications. We take a medication history during intake and advise consulting a prescriber when in doubt.</p>
        </div>
      </div>
      <p class="safety-note">Safety note: The information here is educational and not medical advice. If you have a health condition, please consult a healthcare professional.</p>
    </section>

    <!-- CTA / Membership -->
    <section class="membership-cta" style="background: linear-gradient(180deg, rgba(234,217,199,0.06), rgba(215,185,150,0.02));">
      <div class="container">
        <div class="cta-inner">
          <div>
            <h2>Join the membership: gentle rituals, seasonal blends</h2>
            <p>Monthly gatherings, three custom blends per year, priority booking, and a library of safety-first resources. Membership is about practice and learning.</p>
            <a class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">Start with {{PRIMARY_CTA_LABEL}}</a>
          </div>
          <div class="cta-form">
            <form id="joinForm" action="#" onsubmit="return false;">
              <label for="email">Email</label>
              <input id="email" name="email" type="email" placeholder="you@domain.com" required />
              <button class="btn" id="joinBtn">Request Invite</button>
            </form>
            <p class="muted">Membership includes a safety consult. No medical claims are made.</p>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{TAGLINE}}</p>
      </div>
      <div>
        <p>Phone: {{PHONE}}</p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <nav>
          <a href="/about.html">About</a> • <a href="/book.html">Book</a> • <a href="/contact.html">Contact</a>
        </nav>
      </div>
    </div>
    <small class="legal">&copy; <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved. Practice is supportive and informational, not medical advice.</small>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
