{"path":"assets/css/styles.css","content":"/* Earthy warm theme - no external assets */
:root{
  --bg:#FBF7F2;
  --card:#FFFFFF;
  --muted:#7B6A5A;
  --accent:#C89A6B;
  --accent-dark:#8B5E3B;
  --green:#7A946B;
  --glass: rgba(255,255,255,0.6);
  --shadow: 0 8px 24px rgba(43,33,24,0.08);
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; background:var(--bg); color:#2b2b2b; -webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg, rgba(200,154,107,0.06), rgba(122,148,107,0.03));backdrop-filter: blur(3px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(0,0,0,0.03)}
.nav-wrap{display:flex;align-items:center;justify-content:space-between;padding:14px 18px}
.brand{font-weight:700;color:var(--accent-dark);text-decoration:none;font-size:1.125rem}
.main-nav{display:flex;gap:14px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.main-nav a:hover{background:var(--glass)}
.nav-toggle{display:none;background:none;border:0;font-size:1.25rem}

/* Hero */
.hero{padding:64px 0;background-repeat:repeat; background-size:420px 420px}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:center}
.hero-copy h1{font-family:Georgia, 'Times New Roman', serif;font-size:2.1rem;margin:0 0 12px;color:#3f2d2a}
.lead{color:var(--muted);margin-bottom:18px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;border:1px solid transparent;text-decoration:none;color:#fff;background:var(--accent-dark);cursor:pointer}
.btn.ghost{background:transparent;color:var(--accent-dark);border-color:rgba(139,94,59,0.12)}
.primary-cta{background:linear-gradient(180deg,var(--accent),var(--accent-dark));box-shadow: 0 8px 18px rgba(139,94,59,0.12)}
.small{font-size:0.875rem;color:var(--muted)}
.hero-art .bottle{width:100%;height:auto}

/* Myth vs truth */
.myth-truth{padding:42px 0}
.myth-truth h2{font-family:Georgia, serif;color:#51382d}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.card{background:var(--card);padding:16px;border-radius:12px;box-shadow:var(--shadow)}
.card h3{margin:0 0 8px;color:#5a3f35}
.card .truth{color:var(--muted)}

/* Pillars */
.pillars{padding:40px 0}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.pillar{background:linear-gradient(180deg, rgba(255,255,255,0.7), rgba(250,246,240,0.6));padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.pillar .icon{width:44px;height:44px}
.pillar h3{margin:12px 0 6px;color:#4a382f}
.pillar p{color:var(--muted)}

/* Case notes */
.case-notes{padding:36px 0}
.note-list{display:grid;gap:12px}
.note{background:var(--card);padding:14px;border-radius:10px;border-left:4px solid rgba(200,154,107,0.16)}
.note h4{margin:0 0 6px}
.note p{margin:6px 0;color:var(--muted)}

/* FAQ */
.faq{padding:36px 0}
.faq-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.faq-item{background:var(--card);padding:16px;border-radius:10px;box-shadow:var(--shadow)}
.faq-item h4{margin:0 0 8px}
.safety-note{margin-top:12px;font-size:0.9rem;color:var(--muted)}

/* CTA */
.membership-cta{padding:34px 0}
.cta-inner{display:flex;gap:20px;align-items:center;justify-content:space-between}
.cta-form{background:var(--card);padding:12px;border-radius:10px}
.cta-form input{padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);width:220px}
.cta-form label{display:block;font-size:0.9rem;color:var(--muted);margin-bottom:6px}
.muted{color:var(--muted);font-size:0.9rem}

/* Footer */
.site-footer{padding:22px 0;border-top:1px solid rgba(0,0,0,0.03);margin-top:40px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.legal{display:block;margin-top:10px;color:var(--muted)}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .main-nav{display:none;position:absolute;right:18px;top:64px;background:var(--card);padding:12px;border-radius:8px;box-shadow:var(--shadow)}
  .nav-toggle{display:block}
  .cards{grid-template-columns:1fr}
  .grid-3{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .cta-inner{flex-direction:column;align-items:flex-start}
}

/* small interactive ripple helper */
.ripple{position:relative;overflow:hidden}
.ripple::after{content:"";position:absolute;border-radius:50%;transform:scale(0);opacity:0.4;background:rgba(255,255,255,0.4);transition:transform 0.6s, opacity 0.8s}
.ripple.active::after{transform:scale(6);opacity:0}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Basic UI: nav toggle, form handling, ripple effect and year
  document.addEventListener('DOMContentLoaded', function(){
    var navToggle = document.getElementById('navToggle');
    var mainNav = document.getElementById('mainNav');
    var yearEl = document.getElementById('year');
    if(navToggle){navToggle.addEventListener('click', function(){
      if(mainNav.style.display === 'flex'){mainNav.style.display = '';} else {mainNav.style.display = 'flex';}
    });}
    if(yearEl){yearEl.textContent = new Date().getFullYear();}

    // Join form: simple validation and faux submit
    var joinForm = document.getElementById('joinForm');
    var joinBtn = document.getElementById('joinBtn');
    if(joinForm){
      joinForm.addEventListener('submit', function(e){
        e.preventDefault();
        var email = joinForm.querySelector('input[type="email"]').value;
        if(!email || !email.includes('@')){
          alert('Please provide a valid email address.');
          return;
        }
        joinBtn.textContent = 'Request sent';
        joinBtn.disabled = true;
        setTimeout(function(){
          joinBtn.textContent = 'Request Invite';
          joinBtn.disabled = false;
          joinForm.querySelector('input[type="email"]').value = '';
          alert('Thanks — we will be in touch with membership details.');
        },1200);
      });
    }

    // Ripple effect for primary CTAs
    var ctas = document.querySelectorAll('.primary-cta');
    ctas.forEach(function(btn){
      btn.classList.add('ripple');
      btn.addEventListener('click', function(e){
        var el = e.currentTarget;
        el.classList.remove('active');
        void el.offsetWidth; // reflow
        el.classList.add('active');
      });
    });

    // Small accessibility: add focus outlines for keyboard users
    function handleFirstTab(e){
      if(e.key === 'Tab'){
        document.body.classList.add('user-is-tabbing');
        window.removeEventListener('keydown', handleFirstTab);
      }
    }
    window.addEventListener('keydown', handleFirstTab);
  });
})();"} 
